document.body.dataset.reference='payment-review';
const H=TurboUI,content=document.getElementById('content'),footer=document.getElementById('footer');const previousAmount=new URLSearchParams(location.search).get('amount');let amount=previousAmount&&/^\d+(?:\.\d{1,2})?$/.test(previousAmount)&&Number(previousAmount)>=1&&Number(previousAmount)<=1000000?previousAmount:'2500',amountField;
const merchantMark=document.createElement('span');merchantMark.className='merchant-mark';merchantMark.textContent='N';document.getElementById('page-header').append(H.pageHeader({heading:'Nykaa',subtext:'nykaaphoenixblr@hdfcbank',verified:true,visual:merchantMark}));
document.getElementById('statusbar').append(H.statusbar());document.getElementById('nav').append(H.navigation({title:'Review payment',left:{label:'Back to Hub',icon:'back',href:'../hub-dashboard/index.html'}}));
amountField=H.field({id:'amount',label:'Amount',value:amount,prefix:'₹',prominent:true,type:'text',onInput:v=>{amount=v;amountField.setError('')}});amountField.control.inputMode='decimal';content.append(amountField);
const messageHost=document.createElement('div');messageHost.className='message-action';messageHost.append(H.button({label:'＋ Add message',quiet:true,onClick:()=>{messageHost.className='message-field';const field=H.field({id:'message',label:'Message',optional:true,placeholder:'What is this payment for?'});messageHost.replaceChildren(field);field.control.focus()}}));content.append(messageHost);
const title=document.createElement('h2');title.className='payment-title';title.textContent='Pay Using';content.append(title,H.paymentAccount({onChange:()=>{}}));
function renderAction(){footer.replaceChildren(H.swipeAction({id:'pay',onComplete:()=>{const value=Number(amount);if(!/^\d+(?:\.\d{1,2})?$/.test(amount.trim())||!Number.isFinite(value)||value<1||value>1000000){amountField.setError('Enter an amount between ₹1 and ₹10,00,000.');amountField.control.focus();renderAction();return}TurboStoryContext.navigate('../request-pending/index.html?amount='+encodeURIComponent(value));}}))}renderAction();
